// These tests are skipped unless a corpus has been generated by
// tools/make_thumb_corpus.py. They deliberately do not need MyGo's UI or a
// window: renderThumb is the expensive path and is safe to call directly.
//
//	$env:FLOWVISION_THUMB_CORPUS = "testdata\thumb-corpus"
//	go test -count=1 -tags mygo_nowebview -run TestThumbBaseline -v .

type benchResult struct {
	Name       string  `json:"name"`
	Files      int     `json:"files"`
	WallMS     float64 `json:"wallMs"`
	PerFileMS  float64 `json:"perFileMs"`
	AvgBytes   float64 `json:"avgBytes"`
	TotalBytes int64   `json:"totalBytes"`
	HeapBytes  uint64  `json:"heapBytes"`
	TotalAlloc uint64  `json:"totalAlloc"`
	Note       string  `json:"note,omitempty"`
}

func corpusDir(t *testing.T) string {
	t.Helper()
	dir := os.Getenv("FLOWVISION_THUMB_CORPUS")
	if dir == "" {
		dir = filepath.Join("testdata", "thumb-corpus")
	}
	if _, err := os.Stat(filepath.Join(dir, "dirs")); err != nil {
		t.Skip("thumbnail corpus not found; run tools/make_thumb_corpus.py --full")
	}
	return dir
}

func corpusFiles(t *testing.T, dir, sub string) []string {
	t.Helper()
	matches, err := filepath.Glob(filepath.Join(dir, "dirs", sub, "*.jpg"))
	if err != nil || len(matches) == 0 {
		t.Skipf("no JPEGs in %s/%s", dir, sub)
	}
	sort.Strings(matches)
	return matches
}

func itemsForFiles(paths []string) []*Item {
	out := make([]*Item, 0, len(paths))
	for _, p := range paths {
		st, err := os.Stat(p)
		if err != nil {
			continue
		}
		out = append(out, &Item{
			ID:    filepath.Base(p),
			Name:  filepath.Base(p),
			Path:  p,
			Kind:  "image",
			Ext:   ".jpg",
			Size:  st.Size(),
			Mtime: st.ModTime().Unix(),
		})
	}
	return out
}

func measureThumbPass(t *testing.T, name string, items []*Item, workers int) benchResult {
	t.Helper()
	runtime.GC()
	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)

	var mu sync.Mutex
	var totalBytes int64
	var maxAlloc uint64
	sem := make(chan struct{}, workers)
	var wg sync.WaitGroup
	start := time.Now()
	for _, it := range items {
		it := it
		wg.Add(1)
		go func() {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()
			rendered, err := renderThumb(it, 220)
			if err != nil {
				t.Logf("render %s: %v", it.Name, err)
				return
			}
			data := rendered.Data
			bmp, err := ui.DecodeBitmap(data)
			if err == nil && bmp != nil {
				bmp.ReleasePixels()
			}
			mu.Lock()
			totalBytes += int64(len(data))
			mu.Unlock()
			var m runtime.MemStats
			runtime.ReadMemStats(&m)
			if m.HeapAlloc > maxAlloc {
				maxAlloc = m.HeapAlloc
			}
		}()
	}
	wg.Wait()
	wall := time.Since(start)
	runtime.GC()
	runtime.ReadMemStats(&after)
	n := len(items)
	res := benchResult{
		Name:       name,
		Files:      n,
		WallMS:     float64(wall.Microseconds()) / 1000,
		PerFileMS:  float64(wall.Microseconds()) / 1000 / float64(n),
		TotalBytes: totalBytes,
		AvgBytes:   float64(totalBytes) / float64(n),
		HeapBytes:  after.HeapAlloc,
		TotalAlloc: after.TotalAlloc - before.TotalAlloc,
		Note:       fmt.Sprintf("workers=%d maxHeap=%dMB", workers, maxAlloc>>20),
	}
	t.Logf("%s: %d files, wall %.0fms, avg %.1fms/file, avg %.0fKB, total alloc %dMB, note=%s",
		name, n, res.WallMS, res.PerFileMS, res.AvgBytes/1024, res.TotalAlloc>>20, res.Note)
	return res
}

func TestWICOne(t *testing.T) {
	dir := corpusDir(t)
	files := corpusFiles(t, dir, "24")
	items := itemsForFiles(files)
	rendered, err := wicThumb(items[0], 220)
	if err != nil {
		t.Fatalf("wic: %v", err)
	}
	t.Logf("WIC %s: %d bytes", items[0].Name, len(rendered.Data))
}

func TestThumbBaselineProbe(t *testing.T) {
	dir := corpusDir(t)
	files := corpusFiles(t, dir, "100")
	items := itemsForFiles(files)
	for _, it := range items {
		forgetDims(it.Path)
	}
	runtime.GC()
	start := time.Now()
	fillDims(items, 900)
	wall := time.Since(start)
	t.Logf("probe 100: %.0fms total, %.1fms/file", float64(wall.Microseconds())/1000, float64(wall.Microseconds())/1000/float64(len(items)))
}

