// TestCorpusOrientation verifies that every EXIF orientation produces an
// upright output box: 1-4 stay landscape, 5-8 must be portrait after the swap.
func TestCorpusOrientation(t *testing.T) {
	dir := corpusDir(t)
	matches, _ := filepath.Glob(filepath.Join(dir, "orientation", "*.jpg"))
	if len(matches) != 8 {
		t.Skipf("orientation corpus has %d files, want 8", len(matches))
	}
	for _, p := range matches {
		st, err := os.Stat(p)
		if err != nil {
			continue
		}
		var n int
		if _, err := fmt.Sscanf(filepath.Base(p), "orient-%d.jpg", &n); err != nil {
			t.Fatalf("parse %s: %v", p, err)
		}
		it := &Item{ID: filepath.Base(p), Name: filepath.Base(p), Path: p, Kind: "image", Ext: ".jpg", Size: st.Size(), Mtime: st.ModTime().Unix()}
		rendered, err := renderThumb(it, 220)
		if err != nil {
			t.Fatalf("%s: %v", it.Name, err)
		}
		cfg, err := jpeg.DecodeConfig(bytes.NewReader(rendered.Data))
		if err != nil {
			t.Fatalf("%s: decode config: %v", it.Name, err)
		}
		portrait := cfg.Height > cfg.Width
		if (n >= 5) != portrait {
			t.Fatalf("%s rendered %dx%d, portrait=%v for orientation %d", it.Name, cfg.Width, cfg.Height, portrait, n)
		}
		t.Logf("%-12s %dx%d", it.Name, cfg.Width, cfg.Height)
	}
}

func TestEmbeddedExtract(t *testing.T) {
	dir := corpusDir(t)
	files := corpusFiles(t, dir, "24")
	count := 0
	for _, p := range files {
		if b, err := readEmbeddedJPEG(p); err == nil && len(b) > 0 {
			count++
			if count == 1 {
				t.Logf("embedded %s: %d bytes", filepath.Base(p), len(b))
			}
		}
	}
	t.Logf("embedded thumbnails in 24: %d", count)
}

