// TestBackendQuality compares WIC's final thumbnail with the old Go decoder
// on the same card size. PSNR is a coarse guard against a colour swap or a
// half-sized image; visual review still decides edge softness.
func TestBackendQuality(t *testing.T) {
	dir := corpusDir(t)
	var paths []string
	for _, sub := range []string{"real", "orient"} {
		matches, _ := filepath.Glob(filepath.Join(dir, sub, "*"))
		paths = append(paths, matches...)
	}
	for _, p := range paths {
		st, err := os.Stat(p)
		if err != nil || st.IsDir() {
			continue
		}
		it := &Item{ID: filepath.Base(p), Name: filepath.Base(p), Path: p, Kind: "image", Ext: filepath.Ext(p), Size: st.Size(), Mtime: st.ModTime().Unix()}
		goData, goErr := renderThumbWithBackend(it, 220, "go")
		wicData, wicErr := renderThumbWithBackend(it, 220, "wic")
		if goErr != nil || wicErr != nil {
			t.Logf("%-22s go=%v wic=%v", it.Name, goErr, wicErr)
			continue
		}
		a, err1 := jpeg.Decode(bytes.NewReader(goData))
		b, err2 := jpeg.Decode(bytes.NewReader(wicData))
		if err1 != nil || err2 != nil || a.Bounds() != b.Bounds() {
			t.Logf("%-22s decode/bounds mismatch %v %v %v %v", it.Name, err1, err2, a.Bounds(), b.Bounds())
			continue
		}
		psnr, mse, mae := imageDiff(a, b)
		t.Logf("%-22s %dx%d PSNR %.1fdB RMSE %.1f MAE %.1f", it.Name, a.Bounds().Dx(), a.Bounds().Dy(), psnr, math.Sqrt(mse), mae)
	}
}

func renderThumbWithBackend(it *Item, size int, backend string) ([]byte, error) {
	old := os.Getenv("FLOWVISION_THUMB_BACKEND")
	_ = os.Setenv("FLOWVISION_THUMB_BACKEND", backend)
	defer os.Setenv("FLOWVISION_THUMB_BACKEND", old)
	rendered, err := renderThumb(it, size)
	return rendered.Data, err
}

func imageDiff(a, b image.Image) (psnr, mse, mae float64) {
	var sumSq, sumAbs float64
	var n int
	for y := a.Bounds().Min.Y; y < a.Bounds().Max.Y; y++ {
		for x := a.Bounds().Min.X; x < a.Bounds().Max.X; x++ {
			ar, ag, ab, _ := a.At(x, y).RGBA()
			br, bg, bb, _ := b.At(x, y).RGBA()
			for _, d := range []int64{int64(ar>>8) - int64(br>>8), int64(ag>>8) - int64(bg>>8), int64(ab>>8) - int64(bb>>8)} {
				sumSq += float64(d * d)
				if d < 0 {
					d = -d
				}
				sumAbs += float64(d)
				n++
			}
		}
	}
	mse = sumSq / float64(n)
	mae = sumAbs / float64(n)
	if mse == 0 {
		return 99, 0, 0
	}
	return 10 * math.Log10(255*255/mse), mse, mae
}

func TestThumbBaseline(t *testing.T) {
	dir := corpusDir(t)
	tests := []struct {
		sub     string
		workers int
	}{
		{"24", 6},
		{"100", 6},
		{"300", 6},
	}
	var all []benchResult
	for _, tc := range tests {
		items := itemsForFiles(corpusFiles(t, dir, tc.sub))
		for _, it := range items {
			it.W, it.H = 0, 0
			forgetDims(it.Path)
		}
		// Warm the dimension cache the way Browse's fillDims does before the
		// grid asks for thumbnails.
		fillDims(items, len(items))
		all = append(all, measureThumbPass(t, "baseline-"+tc.sub, items, tc.workers))
	}
	if out := os.Getenv("FLOWVISION_BENCH_OUT"); out != "" {
		data, _ := json.MarshalIndent(all, "", "  ")
		_ = os.WriteFile(out, data, 0o644)
		t.Logf("wrote %s", out)
	}
}
